use std::path::PathBuf;
use std::{env, fs};

/// Which GPU backend to use.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GpuBackend {
    Cuda,
    Hip,
    /// Intel GPUs, through SYCL (oneAPI `icpx`): see `build_sycl`.
    Sycl,
}

fn cbindgen_builder() -> cbindgen::Builder {
    /// The warning placed in the cbindgen header.
    const AUTOGEN_WARNING: &str =
        "/* Automatically generated by `cbindgen`. Not intended for manual editing. */";

    // Generate a header containing bindings to the crate.
    cbindgen::Builder::new()
        .with_pragma_once(true)
        .with_autogen_warning(AUTOGEN_WARNING)
        .with_no_includes()
        .with_sys_include("cstdint")
        .with_parse_deps(true)
        .with_parse_include(&[
            "sp1-hypercube",
            "sp1-primitives",
            "p3-koala-bear",
            "sp1-core-machine",
            "slop-koala-bear",
            "sp1-core-executor",
            "sp1-recursion-executor",
            "sp1-recursion-machine",
        ])
        .with_parse_extra_bindings(&[
            "sp1-hypercube",
            "p3-koala-bear",
            "slop-koala-bear",
            "sp1-recursion-executor",
            "sp1-recursion-machine",
            "sp1-core-machine",
        ])
        .rename_item("KoalaBear", "KoalaBearP3")
        .include_item("GlobalInteractionEvent")
        .include_item("GlobalCols")
        .include_item("MemoryAccessColsChips")
        .include_item("Poseidon2Instr")
        .include_item("Poseidon2PreprocessedColsWide")
        .include_item("Poseidon2Event")
        .include_item("SelectInstr")
        .include_item("SelectPreprocessedCols")
        .include_item("SelectEvent")
        .include_item("SelectCols")
        .include_item("BaseAluInstr")
        .include_item("BaseAluAccessCols")
        .include_item("BaseAluEvent")
        .include_item("BaseAluValueCols")
        .include_item("ExtAluInstr")
        .include_item("ExtAluAccessCols")
        .include_item("ExtAluEvent")
        .include_item("ExtAluValueCols")
        .include_item("ExtFeltInstr")
        .include_item("ExtFeltEvent")
        .include_item("ConvertAccessCols")
        .include_item("ConvertValueCols")
        .include_item("Poseidon2LinearLayerAccessCols")
        .include_item("Poseidon2LinearLayerValueCols")
        .include_item("Poseidon2LinearLayerInstr")
        .include_item("Poseidon2SBoxInstr")
        .include_item("Poseidon2SBoxIo")
        .include_item("Poseidon2SBoxAccessCols")
        .include_item("Poseidon2SBoxValueCols")
        .include_item("NUM_CONVERT_ENTRIES_PER_ROW")
        .include_item("NUM_LINEAR_ENTRIES_PER_ROW")
        .include_item("NUM_SBOX_ENTRIES_PER_ROW")
        .include_item("PERMUTATION_WIDTH")
        .include_item("PrefixSumChecksEvent")
        .include_item("PrefixSumChecksCols")
        .with_namespace("sp1_gpu_sys")
        .with_crate(env::var("CARGO_MANIFEST_DIR").unwrap())
}

/// Place a relative symlink pointing to `original` at `link`.
fn rel_symlink_file<P, Q>(original: P, link: Q)
where
    P: AsRef<std::path::Path>,
    Q: AsRef<std::path::Path>,
{
    #[cfg(unix)]
    use std::os::unix::fs::symlink;
    #[cfg(windows)]
    use std::os::windows::fs::symlink_file as symlink;

    let target_dir = link.as_ref().parent().unwrap();
    fs::create_dir_all(target_dir).unwrap();
    let _ = fs::remove_file(&link);
    let relpath = pathdiff::diff_paths(original, target_dir).unwrap();
    // These links are for IDEs only. Windows allows creating symlinks only with Developer Mode
    // or as an administrator, so don't fail the build over one.
    if let Err(e) = symlink(relpath, link.as_ref()) {
        println!("cargo:warning=could not link {}: {e}", link.as_ref().display());
    }
}

/// Check if CUDA is available on this system.
fn detect_cuda() -> bool {
    // Track rerun-if-env-changed for the explicit override
    println!("cargo:rerun-if-env-changed=SP1_CUDA_ENABLED");

    // 1. Check explicit SP1_CUDA_ENABLED env var
    if let Ok(val) = env::var("SP1_CUDA_ENABLED") {
        match val.to_lowercase().as_str() {
            "0" | "false" => return false,
            "1" | "true" => return true,
            _ => {} // Fall through to auto-detection
        }
    }

    // 2. Try running nvcc --version
    if std::process::Command::new("nvcc")
        .arg("--version")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
    {
        return true;
    }

    // 3. Check CUDA_PATH env var
    if env::var("CUDA_PATH").is_ok() {
        return true;
    }

    // 4. Check common CUDA installation paths
    if std::path::Path::new("/usr/local/cuda/bin/nvcc").exists() {
        return true;
    }
    if std::path::Path::new("/opt/cuda/bin/nvcc").exists() {
        return true;
    }

    false
}

/// Check if HIP/ROCm is available on this system.
fn detect_hip() -> bool {
    // Track rerun-if-env-changed for the explicit override
    println!("cargo:rerun-if-env-changed=SP1_HIP_ENABLED");

    // 1. Check explicit SP1_HIP_ENABLED env var
    if let Ok(val) = env::var("SP1_HIP_ENABLED") {
        match val.to_lowercase().as_str() {
            "0" | "false" => return false,
            "1" | "true" => return true,
            _ => {} // Fall through to auto-detection
        }
    }

    // 2. Try running hipcc --version
    if std::process::Command::new("hipcc")
        .arg("--version")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
    {
        return true;
    }

    // 3. Check ROCM_PATH env var
    if env::var("ROCM_PATH").is_ok() {
        return true;
    }

    // 4. Check HIP_PATH env var
    if env::var("HIP_PATH").is_ok() {
        return true;
    }

    // 5. Check common ROCm installation paths
    for path in &["/opt/rocm/bin/hipcc", "/opt/rocm-7.2.0/bin/hipcc"] {
        if std::path::Path::new(path).exists() {
            return true;
        }
    }

    false
}

/// Determine which GPU backend to use.
///
/// Priority:
/// 1. SP1_GPU_BACKEND=hip|cuda — explicit override
/// 2. SP1_HIP_ENABLED=1 — forces HIP
/// 3. SP1_CUDA_ENABLED=1 — forces CUDA
/// 4. Auto-detect: prefer CUDA if available, fall back to HIP
fn select_gpu_backend() -> Option<GpuBackend> {
    println!("cargo:rerun-if-env-changed=SP1_GPU_BACKEND");

    // Explicit backend selection
    if let Ok(val) = env::var("SP1_GPU_BACKEND") {
        match val.to_lowercase().as_str() {
            "hip" | "rocm" | "amd" => return Some(GpuBackend::Hip),
            "sycl" | "intel" | "oneapi" => return Some(GpuBackend::Sycl),
            "cuda" | "nvidia" => return Some(GpuBackend::Cuda),
            "none" | "off" => return None,
            _ => {} // Fall through
        }
    }

    // Check explicit enable flags
    if let Ok(val) = env::var("SP1_HIP_ENABLED") {
        if val == "1" || val.to_lowercase() == "true" {
            return Some(GpuBackend::Hip);
        }
    }

    // Auto-detect: prefer CUDA, fall back to HIP
    if detect_cuda() {
        return Some(GpuBackend::Cuda);
    }
    if detect_hip() {
        return Some(GpuBackend::Hip);
    }

    None
}

/// Resolve the CUDA toolkit root directory, trying sources in order:
/// 1. `CUDA_PATH` env var
/// 2. `CUDACXX` env var (path to nvcc → its grandparent)
/// 3. `nvcc` on PATH (via `which`)
/// 4. `/usr/local/cuda/bin/nvcc`'s resolved symlink target grandparent
/// 5. `/usr/local/cuda` as a last-resort default
///
/// Used for BOTH setting `CMAKE_CUDA_COMPILER` (so CMake compiles against the
/// matching headers) and setting the Rust `link-search` path (so we link the
/// matching `libcudart`). Keeping these in sync avoids the `cudaDeviceProp`
/// struct ABI mismatch that silently corrupts `multiProcessorCount` when
/// CMake uses CUDA 13 nvcc but Rust links 12's libcudart (or vice versa).
fn resolve_cuda_toolkit_path() -> String {
    if let Ok(v) = env::var("CUDA_PATH") {
        if !v.is_empty() {
            return v;
        }
    }
    if let Ok(cudacxx) = env::var("CUDACXX") {
        if let Some(root) = std::path::Path::new(&cudacxx).parent().and_then(|p| p.parent()) {
            return root.to_string_lossy().into_owned();
        }
    }
    if let Ok(output) = std::process::Command::new("which").arg("nvcc").output() {
        if output.status.success() {
            if let Ok(path) = String::from_utf8(output.stdout) {
                let path = path.trim();
                if !path.is_empty() {
                    if let Some(root) = std::path::Path::new(path).parent().and_then(|p| p.parent())
                    {
                        return root.to_string_lossy().into_owned();
                    }
                }
            }
        }
    }
    // No env hints — search /usr/local/cuda-*. Prefer higher major versions
    // because CUDA 12.x ptxas rejects the G2 MSM `accumulate` kernel's
    // register count, while CUDA 13.x compiles the same code fine. When a
    // distribution ships multiple toolkits side-by-side, we want the newer
    // one even if `/usr/local/cuda` symlinks to the older one.
    if let Ok(entries) = std::fs::read_dir("/usr/local") {
        let mut candidates: Vec<(u32, u32, String)> = entries
            .filter_map(|e| e.ok())
            .filter_map(|entry| {
                let name = entry.file_name().to_string_lossy().into_owned();
                let rest = name.strip_prefix("cuda-")?;
                let mut parts = rest.split('.');
                let major: u32 = parts.next()?.parse().ok()?;
                let minor: u32 = parts.next().and_then(|s| s.parse().ok()).unwrap_or(0);
                let root = format!("/usr/local/{}", name);
                if std::path::Path::new(&format!("{root}/bin/nvcc")).exists() {
                    Some((major, minor, root))
                } else {
                    None
                }
            })
            .collect();
        // Newest first (by major, then minor)
        candidates.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| b.1.cmp(&a.1)));
        if let Some((_, _, root)) = candidates.into_iter().next() {
            return root;
        }
    }
    // Last resort — follow whatever /usr/local/cuda points at.
    let default_nvcc = std::path::Path::new("/usr/local/cuda/bin/nvcc");
    if default_nvcc.exists() {
        if let Ok(resolved) = default_nvcc.canonicalize() {
            if let Some(root) = resolved.parent().and_then(|p| p.parent()) {
                return root.to_string_lossy().into_owned();
            }
        }
    }
    "/usr/local/cuda".to_string()
}

fn main() {
    println!("cargo::rustc-check-cfg=cfg(hip_backend)");
    println!("cargo::rustc-check-cfg=cfg(sycl_backend)");
    // Directives for tracking changes in folders
    println!("cargo:rerun-if-changed=include/");
    println!("cargo:rerun-if-changed=lib/");
    println!("cargo:rerun-if-changed=sppark/");
    println!("cargo:rerun-if-changed=CMakeLists.txt");
    // Directives for tracking changes in compilation profiles
    println!("cargo:rerun-if-env-changed=PROFILE");
    println!("cargo:rerun-if-env-changed=OPT_LEVEL");
    println!("cargo:rerun-if-env-changed=DEBUG");
    println!("cargo:rerun-if-env-changed=CUDA_ARCHS");
    println!("cargo:rerun-if-env-changed=CUPQC_SDK_DIR");
    println!("cargo:rerun-if-env-changed=CUDA_PATH");
    println!("cargo:rerun-if-env-changed=CUDACXX");
    println!("cargo:rerun-if-env-changed=PROFILE_DEBUG_DATA");

    // The crate directory.
    let crate_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());

    // The output directory, where built artifacts should be placed.
    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());

    // The directory to place headers into.
    let out_include_dir = out_dir.join("include");
    const INCLUDE_DIRNAME: &str = "include";

    // Generate cbindgen headers BEFORE building with CMake
    let cbindgen_hpp = "sp1-gpu-cbindgen.hpp";
    let header_path = out_include_dir.join(cbindgen_hpp);

    match cbindgen_builder().generate() {
        Ok(bindings) => {
            fs::create_dir_all(&out_include_dir).unwrap();
            if bindings.write_to_file(&header_path) {
                // Symlink header into `target/include` for IDE purposes
                let mut dir = out_dir.clone();
                while !dir.ends_with("target") {
                    if !dir.pop() {
                        break;
                    }
                }
                if dir.ends_with("target") {
                    rel_symlink_file(&header_path, dir.join(INCLUDE_DIRNAME).join(cbindgen_hpp));
                }
            }
        }
        Err(cbindgen::Error::ParseSyntaxError { .. }) => {
            // Ignore parse errors in the build script.
            // We let rust-analyzer/rustc run to report the syntax error with diagnostics.
            return;
        }
        Err(e) => panic!("{e:?}"),
    }

    // Determine which GPU backend to use
    let backend = match select_gpu_backend() {
        Some(b) => b,
        None => {
            println!(
                "cargo:warning=No GPU backend detected (neither CUDA nor HIP), skipping GPU build"
            );
            return;
        }
    };

    if backend == GpuBackend::Sycl {
        build_sycl(&crate_dir, &out_dir, &out_include_dir);
        return;
    }

    println!("cargo:rerun-if-env-changed=HIP_ARCHS");
    println!("cargo:rerun-if-env-changed=ROCM_PATH");
    println!("cargo:rerun-if-env-changed=HIP_PATH");
    println!("cargo:rerun-if-env-changed=SP1_GPU_BACKEND");

    // Build using CMake
    let mut cmake_config = cmake::Config::new(".");

    let cupqc_sdk_dir = env::var_os("CARGO_FEATURE_NVIDIA_NTT").map(|_| {
        let sdk_dir = env::var_os("CUPQC_SDK_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("/usr/local/cupqc-sdk"));
        let ntt_library = sdk_dir.join("lib/libcupqc-ntt.a");
        assert!(
            ntt_library.is_file(),
            "nvidia-ntt requires cuPQC; set CUPQC_SDK_DIR to the extracted SDK"
        );
        cmake_config.define("NVIDIA_NTT", "ON");
        cmake_config.define("CUPQC_SDK_DIR", &sdk_dir);
        sdk_dir
    });

    // Export compile commands for clangd IDE support
    cmake_config.define("CMAKE_EXPORT_COMPILE_COMMANDS", "ON");

    // Register the hip_backend cfg so Rust's check-cfg doesn't warn on usage.
    println!("cargo:rustc-check-cfg=cfg(hip_backend)");

    match backend {
        GpuBackend::Sycl => unreachable!("built by build_sycl"),
        GpuBackend::Hip => {
            println!("cargo:warning=Building with HIP/ROCm backend for AMD GPUs");
            println!("cargo:rustc-cfg=hip_backend");

            // Tell CMakeLists.txt to use the HIP path
            cmake_config.define("USE_HIP", "ON");

            let rocm_path = rocm_path();

            // Point CMake at the ROCm installation
            cmake_config.define("CMAKE_PREFIX_PATH", &rocm_path);

            if env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc") {
                configure_msvc_hip(&mut cmake_config, &rocm_path);
            } else {
                // Use the AMD clang compiler directly (CMake 4.x rejects hipcc wrapper).
                // The ROCm clang at lib/llvm/bin/clang++ handles HIP natively.
                let clang_path = format!("{}/lib/llvm/bin/clang++", rocm_path);
                if std::path::Path::new(&clang_path).exists() {
                    cmake_config.define("CMAKE_HIP_COMPILER", &clang_path);
                }
                // If clang++ not found, let CMake auto-detect
            }

            // Pass HIP architectures if explicitly set
            if let Ok(hip_archs) = env::var("HIP_ARCHS") {
                cmake_config.define("HIP_ARCHS", &hip_archs);
            }
        }
        GpuBackend::Cuda => {
            // Pass CUDA architectures to CMake only if explicitly set
            // Otherwise, CMake will use its own version-based defaults
            if let Ok(cuda_archs) = env::var("CUDA_ARCHS") {
                cmake_config.define("CUDA_ARCHS", &cuda_archs);
            }

            // CRITICAL: pin CMake's CUDA compiler to the same toolkit that
            // we'll link libcudart from. The `cudaDeviceProp` struct layout
            // changed between CUDA 12 and CUDA 13; if CMake compiles against
            // 13 headers but we link 12's libcudart (or vice versa),
            // `cudaGetDeviceProperties` returns garbage for
            // `multiProcessorCount` and sppark's MSM launches die with
            // `cudaErrorInvalidConfiguration` (grid_size = sm_count/3 = 0).
            // We deliberately resolve the toolkit the same way the link
            // search path logic below resolves it, so both sides agree.
            let resolved = resolve_cuda_toolkit_path();
            let nvcc_path = format!("{resolved}/bin/nvcc");
            if std::path::Path::new(&nvcc_path).exists() {
                cmake_config.define("CMAKE_CUDA_COMPILER", &nvcc_path);
            }
            if env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc") {
                configure_msvc_ninja(&mut cmake_config);
            }
        }
    }

    // Pass cbindgen include directory
    cmake_config.define("CBINDGEN_INCLUDE_DIR", out_include_dir.display().to_string());

    // Pass profile debug flag if set
    if let Some(profile_debug_data) = env::var_os("PROFILE_DEBUG_DATA") {
        if profile_debug_data == "true" {
            cmake_config.define("PROFILE_DEBUG_DATA", "true");
        }
    }

    // Determine build type based on profile
    let profile = env::var("PROFILE").unwrap_or_else(|_| "release".to_string());
    if profile == "debug" {
        cmake_config.profile("Debug");
    } else {
        cmake_config.profile("Release");
    }

    // Build via CMake
    let dst = cmake_config.build();

    // Symlink compile_commands.json to project root for clangd
    let compile_commands_src = dst.join("build").join("compile_commands.json");
    if compile_commands_src.exists() {
        let project_root = crate_dir.join("../..").canonicalize().unwrap();
        rel_symlink_file(&compile_commands_src, project_root.join("compile_commands.json"));
    }

    // Link the static library (named sys-cuda for both backends, for FFI compatibility)
    println!("cargo:rustc-link-search=native={}/lib", dst.display());
    println!("cargo:rustc-link-lib=static=sys-cuda");
    if let Some(sdk_dir) = cupqc_sdk_dir {
        println!("cargo:rustc-link-lib=static:+whole-archive=nvidia-ntt");
        println!("cargo:rustc-link-search=native={}/lib", sdk_dir.display());
        println!("cargo:rustc-link-lib=static=cupqc-ntt");
    }

    let msvc = env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc");
    match backend {
        GpuBackend::Sycl => unreachable!("built by build_sycl"),
        GpuBackend::Hip => {
            // ROCm / HIP library search paths
            let rocm_path = rocm_path();

            println!("cargo:rustc-link-search=native={}/lib", rocm_path);
            println!("cargo:rustc-link-search=native={}/lib64", rocm_path);

            // HIP runtime libraries
            println!("cargo:rustc-link-lib=amdhip64");

            // HIP device runtime for relocatable device code (GPU linking)
            println!("cargo:rustc-link-lib=hiprtc");

            // The caching allocator's VRAM budget query (lib/runtime/stream.cu).
            if msvc {
                println!("cargo:rustc-link-lib=dxgi");
            }
        }
        GpuBackend::Cuda if msvc => {
            // A Windows toolkit keeps its libraries in lib\x64. The runtime is linked
            // statically, so the server needs no cudart64_*.dll beside it.
            if let Ok(cuda_path) = env::var("CUDA_PATH") {
                println!("cargo:rustc-link-search=native={cuda_path}/lib/x64");
            }
            println!("cargo:rustc-link-lib=cudart_static");
            println!("cargo:rustc-link-lib=cudadevrt");
        }
        GpuBackend::Cuda => {
            // Add CUDA library search paths.
            // IMPORTANT: must match the CUDA version used by nvcc to avoid
            // cudaDeviceProp ABI mismatch (struct layout changed between
            // CUDA 12 and 13). `resolve_cuda_toolkit_path` is also used when
            // configuring CMake above, so the two sides stay in sync.
            let cuda_path = resolve_cuda_toolkit_path();
            println!("cargo:rustc-link-search=native={cuda_path}/lib64");
            println!("cargo:rustc-link-search=native={cuda_path}/lib");
            // CUDA 13+ places libraries under targets/<triple>/lib
            println!("cargo:rustc-link-search=native={cuda_path}/targets/x86_64-linux/lib");

            // Link CUDA runtime libraries
            println!("cargo:rustc-link-lib=cudart");
            println!("cargo:rustc-link-lib=cudadevrt");
        }
    }

    // MSVC links its own C++ runtime, and has no libdl.
    if msvc {
        println!("cargo:include={}", out_include_dir.display());
        return;
    }

    // Link system libraries
    println!("cargo:rustc-link-lib=stdc++");
    println!("cargo:rustc-link-lib=dl");
    if backend == GpuBackend::Cuda {
        println!("cargo:rustc-link-lib=gomp");
    }

    // Add include directories for compilation if needed
    println!("cargo:include={}", out_include_dir.display());
}

/// The ROCm installation: `ROCM_PATH`, then `HIP_PATH` (what the Windows HIP SDK sets), then the
/// usual Linux locations.
fn rocm_path() -> String {
    env::var("ROCM_PATH").or_else(|_| env::var("HIP_PATH")).unwrap_or_else(|_| {
        // Auto-detect: check versioned paths first, then generic
        for candidate in &["/opt/rocm-7.2.0", "/opt/rocm"] {
            if std::path::Path::new(candidate).join("bin/hipcc").exists() {
                return candidate.to_string();
            }
        }
        "/opt/rocm".to_string()
    })
}

/// On MSVC, builds the HIP path with Ninja and the HIP SDK's clang for both C++ and HIP.
///
/// CMake refuses to mix clang with cl.exe in one project, and the Windows HIP SDK keeps its clang
/// in `bin` (it has no `lib/llvm`). That clang targets MSVC and links the dynamic C runtime by
/// default, as rustc does; cl.exe's environment (INCLUDE, LIB, PATH) is passed through for the
/// MSVC headers and libraries.
fn configure_msvc_hip(cmake_config: &mut cmake::Config, rocm_path: &str) {
    let cl = cc::Build::new().cpp(true).get_compiler();
    for (key, value) in cl.env() {
        cmake_config.env(key, value);
    }
    let clang = PathBuf::from(rocm_path).join("bin").join("clang++.exe");
    // The flags the cmake crate passes come from this: clang's, not cl.exe's (`-nologo`, ...).
    cmake_config.init_cxx_cfg(cc::Build::new().cpp(true).compiler(&clang).to_owned());
    let clang = clang.to_string_lossy().replace('\\', "/");
    cmake_config.generator("Ninja");
    cmake_config.define("CMAKE_CXX_COMPILER", &clang);
    cmake_config.define("CMAKE_HIP_COMPILER", &clang);
    if let Some(ninja) = bundled_ninja(&cl) {
        cmake_config.define("CMAKE_MAKE_PROGRAM", ninja);
    }
}

/// Visual Studio's ninja.exe, when there is no ninja on PATH.
fn bundled_ninja(cl: &cc::Tool) -> Option<String> {
    if std::process::Command::new("ninja").arg("--version").output().is_ok() {
        return None;
    }
    // cl.exe is at <VS>\VC\Tools\MSVC\<version>\bin\Host<arch>\<arch>\cl.exe: eight up.
    cl.path()
        .ancestors()
        .nth(8)
        .map(|vs| vs.join(r"Common7\IDE\CommonExtensions\Microsoft\CMake\Ninja\ninja.exe"))
        .filter(|ninja| ninja.is_file())
        .map(|ninja| ninja.to_string_lossy().replace('\\', "/"))
}

/// On MSVC, builds with Ninja rather than CMake's default Visual Studio generator.
///
/// The Visual Studio generator does not perform the device link `CUDA_RESOLVE_DEVICE_SYMBOLS`
/// asks for on a static library (the Ninja and Makefile generators do), so `sys-cuda.lib` would
/// lack the `__cudaRegisterLinkedBinary_*` symbols its relocatable objects reference. It also
/// compiles CUDA through Visual Studio's build customization for the newest toolkit installed,
/// rather than the one `CUDA_PATH` names.
///
/// Ninja needs what a Developer shell provides: `cc` finds cl.exe and its environment (INCLUDE,
/// LIB, PATH), and Visual Studio ships a ninja.exe when none is on PATH. The compilers are named
/// explicitly, so CMake cannot pick up another on PATH (a MinGW gcc, say).
fn configure_msvc_ninja(cmake_config: &mut cmake::Config) {
    println!("cargo:rerun-if-env-changed=CUDA_PATH");
    let cl = cc::Build::new().cpp(true).get_compiler();
    for (key, value) in cl.env() {
        cmake_config.env(key, value);
    }
    cmake_config.generator("Ninja");
    cmake_config.define("CMAKE_C_COMPILER", cl.path());
    cmake_config.define("CMAKE_CXX_COMPILER", cl.path());
    if let Ok(cuda_path) = env::var("CUDA_PATH") {
        let nvcc = PathBuf::from(cuda_path).join("bin").join("nvcc.exe");
        cmake_config.define("CMAKE_CUDA_COMPILER", nvcc.to_string_lossy().replace('\\', "/"));
    }
    if let Some(ninja) = bundled_ninja(&cl) {
        cmake_config.define("CMAKE_MAKE_PROGRAM", ninja);
    }
}

